std::vector<PresetInfo> PresetBank::loadFactoryBank() noexcept
{
    std::vector<PresetInfo> bank;

    // Spectral Drift: 26 presets
    for (int i = 0; i < 26; ++i)
    {
        PresetInfo p;
        p.name = sdFactoryPresets[i];
        p.category = "Spectral Drift";
        p.description = "Spectral Drift Shifter factory preset";
        // In a full build the state would be a proper ValueTree; for now use default state
        p.state = std::make_unique<ValueTree>("SpectralDriftState");
        bank.push_back (std::move (p));
    }

    // Dynamic Saturation: 26 presets
    for (int i = 0; i < 26; ++i)
    {
        PresetInfo p;
        p.name = dsFactoryPresets[i];
        p.category = "Dynamic Saturation";
        p.description = "Dynamic Saturation Companion factory preset";
        p.state = std::make_unique<ValueTree>("DynamicSaturationState");
        bank.push_back (std::move (p));
    }

    // Micro Timing Chaos: 28 presets
    for (int i = 0; i < 28; ++i)
    {
        PresetInfo p;
        p.name = mtcFactoryPresets[i];
        p.category = "Micro Timing Chaos";
        p.description = "Micro-Timing Chaos Sequencer factory preset";
        p.state = std::make_unique<ValueTree>("MicroTimingChaosState");
        bank.push_back (std::move (p));
    }

    return bank;
}

ValueTree PresetBank::parseDelta (const juce::String& json, const juce::ValueTree& defaultState)
{
    // Parse a JSON delta and merge it with the default state.
    // A delta is a JSON object whose keys are parameter IDs and values are the
    // new normalised values. Keys that are not present in the default state are
    // ignored.
    
    auto dict = juce::JSON::parse (json);
    if (! dict.isObject())
        return defaultState;

    auto result = defaultState.createChildElement (juce::JuceAppConfig::getAppSettings().getType().toString());
    result = defaultState;  // start from default

    // Copy all children from default first (deep copy is complex, so for now
    // just return the default with any delta overrides applied)
    // TODO: full delta merging when the format is finalised.

    // Apply any numeric overrides from the delta
    for (auto key : dict.getAllKeys())
    {
        const auto value = dict[key];
        if (value.isNumber())
        {
            // Find the parameter with this ID in the result tree and set its value
            // This is a simplified implementation
        }
    }

    return result;
}

String PresetBank::encodeValueTree (const juce::ValueTree& tree)
{
    return juce::JSON::toString (tree);
}

ValueTree PresetBank::decodeJson (const juce::String& json)
{
    // Simple JSON to ValueTree conversion
    // A full implementation would parse the JSON structure and create the appropriate
    // ValueTree hierarchy. For now, just try to parse as a JSON object.
    
    auto var = juce::JSON::parse (json);
    if (var.isObject())
    {
        // Create a ValueTree from the JSON object
        // The tag name would be the type name; for a simple preset we use "preset"
        return ValueTree ("preset", nullptr, &var, nullptr);
    }
    
    return ValueTree();
}

